// ── Node.js instrumentation with prom-client ────────────────────
import express from 'express';
import client from 'prom-client';

const app = express();

// 1. Collect default Node.js metrics (event loop lag, GC, heap, etc.)
client.collectDefaultMetrics({ prefix: 'api_' });

// 2. Counter — total requests, labelable by method, route, status
const httpRequestsTotal = new client.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code'],
});

// 3. Histogram — request duration in seconds, with sensible buckets
const httpRequestDuration = new client.Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP request duration in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5],
});

// 4. Gauge — currently active (in-flight) requests
const activeRequests = new client.Gauge({
  name: 'http_active_requests',
  help: 'Number of in-flight HTTP requests',
});

// 5. Middleware: instrument every request
app.use((req, res, next) => {
  const end = httpRequestDuration.startTimer();
  activeRequests.inc();

  res.on('finish', () => {
    const labels = {
      method: req.method,
      route: req.route?.path ?? req.path,
      status_code: String(res.statusCode),
    };
    httpRequestsTotal.inc(labels);
    end(labels);          // stops timer and records observation
    activeRequests.dec();
  });

  next();
});

// 6. /metrics endpoint scraped by Prometheus
app.get('/metrics', async (req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.send(await client.register.metrics());
});

app.get('/orders/:id', async (req, res) => {
  // ... business logic ...
  res.json({ id: req.params.id, status: 'fulfilled' });
});

app.listen(3000);
console.log('Server on :3000, metrics on :3000/metrics');
